"""The grader harness inlined at the top of every generated test.py (each task must be
self-contained: forge/ab.py copies only test.py into the project after the agent finishes)."""

HARNESS = '"""Hidden test. Not shown to the agent. Run after the arm finishes.\n\nPrints PASS/FAIL per check and SCORE: n/m; exits 0 only on a full score. Each check runs\nwith a time limit, so a hang counts as a failure instead of stalling the run.\n"""\nGRADER_VERSION = 1\nimport importlib, os, sys, threading, time\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE))\nCHECKS = []\n\n\ndef check(name, timeout=20):\n    def register(fn):\n        CHECKS.append((name, fn, timeout))\n        return fn\n    return register\n\n\ndef load(module):\n    """A fresh import of the module the agent edited."""\n    sys.modules.pop(module, None)\n    return importlib.import_module(module)\n\n\ndef main():\n    print("GRADER: behavioral")\n    passed = 0\n    for name, fn, timeout in CHECKS:\n        result = {}\n\n        def run():\n            try:\n                fn()\n                result["ok"] = True\n            except BaseException as exc:  # noqa: BLE001 - every failure is a FAIL line\n                result["error"] = f"{type(exc).__name__}: {exc}"[:300]\n\n        worker = threading.Thread(target=run, daemon=True)\n        worker.start()\n        worker.join(timeout)\n        if worker.is_alive():\n            result["error"] = f"timed out after {timeout}s"\n        if result.get("ok"):\n            passed += 1\n            print(f"PASS {name}")\n        else:\n            print(f"FAIL {name} {result.get(\'error\')}")\n    print(f"SCORE: {passed}/{len(CHECKS)}")\n    sys.stdout.flush()\n    os._exit(0 if passed == len(CHECKS) else 1)\n\n'

FOOTER = '\n\nif __name__ == "__main__":\n    main()\n'
